 96	function mergeAcceptanceCriteriaById(
 97	  existingCriteria: SpecItemInput["acceptance_criteria"] | undefined,
 98	  incomingCriteria: NonNullable<SpecItemInput["acceptance_criteria"]>,
 99	): NonNullable<SpecItemInput["acceptance_criteria"]> {
100	  if (!existingCriteria || existingCriteria.length === 0) {
101	    return incomingCriteria;
102	  }
103	
104	  const incomingById = new Map(incomingCriteria.map(ac => [ac.id, ac]));
105	  const existingIds = new Set(existingCriteria.map(ac => ac.id));
106	  const merged = existingCriteria.map(ac => incomingById.get(ac.id) ?? ac);
107	
108	  for (const ac of incomingCriteria) {
109	    if (!existingIds.has(ac.id)) {
110	      merged.push(ac);
111	    }
112	  }
113	
114	  return merged;
115	}
