117	/**
118	 * Import plan document and create specs/tasks
119	 * AC: @plan-import ac-11 through ac-33
120	 */
121	async function importPlan(
122	  planPath: string,
123	  options: { module: string; dryRun?: boolean; update?: boolean },
124	): Promise<void> {
125	  // JSON mode is set by global preAction hook
126	
127	  const ctx = await initContext();
128	  const author = getAuthor(ctx.config?.identity?.author);
129	
130	  // Read plan file
131	  // AC: @plan-import ac-21 - Handle file read errors
132	  const fullPath = path.resolve(process.cwd(), planPath);
133	  let content: string;
134	  try {
135	    content = await fs.readFile(fullPath, "utf-8");
136	  } catch (err) {
137	    error(`Failed to read plan file: ${planPath}`, err);
138	    process.exit(EXIT_CODES.USAGE_ERROR);
139	  }
140	
141	  // Parse plan document
142	  // AC: @plan-import ac-11, ac-12, ac-13, ac-21, ac-22
143	  const parsed = parsePlanDocument(content);
144	
145	  // Report parsing errors
146	  if (parsed.errors.length > 0) {
147	    for (const err of parsed.errors) {
148	      if (err.type === "yaml") {
149	        // AC: @plan-import ac-21 - YAML parse errors (fatal)
150	        error(err.message);
151	        process.exit(EXIT_CODES.USAGE_ERROR);
152	      } else if (err.type === "validation") {
153	        // AC: @plan-import ac-22 - Validation errors (non-fatal, add to warnings)
154	        warn(err.message);
155	      }
156	    }
157	  }
158	
159	  // Load plans for cross-namespace slug safety
160	  const plans = await loadPlans(ctx);
161	
162	  // Build indexes to check existing specs (include plans for cross-namespace slug safety)
163	  const { refIndex, items } = await buildIndexes(ctx, plans);
164	  const existingSpecRefs = new Set<string>();
165	  for (const item of items) {
166	    for (const slug of (item as LoadedSpecItem).slugs || []) {
167	      existingSpecRefs.add(slug);
168	    }
169	    existingSpecRefs.add(refIndex.shortUlid(item._ulid));
170	  }
171	
172	  // Resolve module reference
173	  const moduleResult = refIndex.resolve(options.module);
174	  if (!moduleResult.ok) {
175	    error(errors.reference.itemNotFound(options.module));
176	    process.exit(EXIT_CODES.NOT_FOUND);
177	  }
178	
179	  const moduleItem = moduleResult.item as LoadedSpecItem;
180	
181	  // Verify it's a module
182	  if (moduleItem.type !== "module") {
183	    error(`${options.module} is not a module (type: ${moduleItem.type})`);
184	    process.exit(EXIT_CODES.USAGE_ERROR);
185	  }
186	
187	  // Validate parent references
188	  // AC: @plan-import ac-17, ac-33
189	  const parentErrors = validateParentRefs(parsed.specs, existingSpecRefs);
190	  parsed.errors.push(...parentErrors);
191	
192	  // Sort specs topologically
193	  // AC: @plan-import ac-16, ac-18
194	  const { sorted, error: sortError } = topologicalSort(parsed.specs);
195	  if (sortError) {
196	    // AC: @plan-import ac-18 - Circular dependency detection
197	    error(sortError.message);
198	    process.exit(EXIT_CODES.USAGE_ERROR);
199	  }
200	
201	  // Create plan record
202	  // AC: @plan-import ac-24, ac-28
203	  // Auto-namespace plan slugs with "plan-" prefix to prevent collision with spec slugs
204	  // Ensure uniqueness across all namespaces (plans + specs + tasks via refIndex)
205	  let planSlug = `plan-${generateSlug(parsed.title)}`;
206	  let counter = 1;
207	  const baseSlug = planSlug;
208	  while (!refIndex.isSlugAvailable(planSlug)) {
209	    planSlug = `${baseSlug}-${counter}`;
210	    counter++;
211	  }
212	
213	  // Track all slugs created during this import (refIndex is stale after mutations)
214	  const importReservedSlugs = new Set<string>([planSlug]);
215	
216	  const planInput: PlanInput = {
217	    title: parsed.title,
218	    content: parsed.content,
219	    status: "active",
220	    slugs: [planSlug],
221	    source_path: fullPath,
222	  };
223	
224	  const newPlan = createPlan(planInput);
225	  const planRef = `@${planSlug}`;
226	
227	  // AC: @plan-import ac-13 - Attach global implementation notes to plan record
228	  if (parsed.implementationNotes) {
229	    newPlan.notes.push({
230	      _ulid: ulid(),
231	      created_at: new Date().toISOString(),
232	      author,
233	      content: `Implementation notes:\n\n${parsed.implementationNotes}`,
234	    });
235	  }
236	
237	  // Initialize result
238	  const result: ImportResult = {
239	    createdSpecs: [],
240	    updatedSpecs: [],
241	    createdTasks: [],
242	    errors: [],
243	    skipped: [],
244	    planRef,
245	  };
246	
247	  // Add parser validation errors to result
248	  // AC: @plan-import ac-22, ac-29 - Include parser validation errors in summary
